import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("submit vendor for review", () => {
  test("submitting with only a w9 lists the missing kinds", { tag: "@REV-02" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Missing Docs Co"),
        category: "services",
        contact_email: "billing@example.com",
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = (await created.json()) as { id: string };

    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
    const document = (await upload.json()) as { id: string };

    // Extraction runs in the background; wait until the w9 is extracted.
    await expect
      .poll(async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        return ((await res.json()) as { status: string }).status;
      })
      .toBe("extracted");

    // Act
    const response = await member.post(`/api/vendors/${vendor.id}/submit`);

    // Assert
    expect(response.status(), await response.text()).toBe(409);
    const error = ((await response.json()) as { error: { code: string; missing_kinds: string[] } })
      .error;
    expect(error.code, await response.text()).toBe("documents_incomplete");
    expect(error.missing_kinds, await response.text()).toEqual(["contract", "insurance_certificate"]);
  });
});
